[{"agent": "coding_agent", "event": "call", "tool": "save_code", "arguments": {"code": "/*
  Two-Wheel Obstacle Avoiding Robot
  ---------------------------------
  This code controls a two-wheel robot to move forward and avoid obstacles
  using an ultrasonic sensor (HC-SR04) and a motor driver (L298N).

  Connections:
  - Ultrasonic Sensor:
    - VCC to 5V
    - GND to GND
    - Trig to Pin 9
    - Echo to Pin 8

  - Motor Driver (L298N):
    - ENA to Pin 5 (Left Motor Speed)
    - IN1 to Pin 6 (Left Motor Direction 1)
    - IN2 to Pin 7 (Left Motor Direction 2)
    - ENB to Pin 3 (Right Motor Speed)
    - IN3 to Pin 12 (Right Motor Direction 1)
    - IN4 to Pin 13 (Right Motor Direction 2)
    - GND to GND
    - VCC to 12V (External Power)
*/

// Ultrasonic Sensor Pins
const int trigPin = 9;
const int echoPin = 8;

// Motor Driver Pins
// Left Motor
const int leftMotorSpeed = 5;
const int leftMotorForward = 6;
const int leftMotorBackward = 7;

// Right Motor
const int rightMotorSpeed = 3;
const int rightMotorForward = 12;
const int rightMotorBackward = 13;

// Variables
long duration;
int distance;
int obstacleDistance = 20; // Distance in cm to trigger avoidance

void setup() {
  // Set motor pins as outputs
  pinMode(leftMotorSpeed, OUTPUT);
  pinMode(leftMotorForward, OUTPUT);
  pinMode(leftMotorBackward, OUTPUT);
  pinMode(rightMotorSpeed, OUTPUT);
  pinMode(rightMotorForward, OUTPUT);
  pinMode(rightMotorBackward, OUTPUT);

  // Set sensor pins
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);

  // Initialize serial communication for debugging
  Serial.begin(9600);

  // Stop robot initially
  stopRobot();
}

void loop() {
  // Get distance from sensor
  distance = getDistance();

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  // Check for obstacles
  if (distance <= obstacleDistance) {
    // Obstacle detected
    stopRobot();
    delay(500);

    // Move backward slightly
    moveBackward(200);
    delay(300);

    // Turn right
    turnRight(500);
    delay(300);

    // Check again after turning
    distance = getDistance();
    if (distance <= obstacleDistance) {
      // If still blocked, turn left
      turnLeft(500);
    }
  } else {
    // No obstacle, move forward
    moveForward();
  }
}

// Function to read distance from ultrasonic sensor
int getDistance() {
  // Clear the trigPin by setting it LOW
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);

  // Set the trigPin HIGH for 10 microseconds
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echoPin, returns the sound wave travel time in microseconds
  duration = pulseIn(echoPin, HIGH);

  // Calculate distance
  distance = duration * 0.034 / 2;

  return distance;
}

// Function to move robot forward
void moveForward() {
  digitalWrite(leftMotorForward, HIGH);
  digitalWrite(leftMotorBackward, LOW);
  digitalWrite(rightMotorForward, HIGH);
  digitalWrite(rightMotorBackward, LOW);

  // Set speed (0-255)
  analogWrite(leftMotorSpeed, 200);
  analogWrite(rightMotorSpeed, 200);
}

// Function to move robot backward
void moveBackward(int durationMs) {
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, HIGH);
  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, HIGH);

  analogWrite(leftMotorSpeed, 150);
  analogWrite(rightMotorSpeed, 150);

  delay(durationMs);
  stopRobot();
}

// Function to turn robot right
void turnRight(int durationMs) {
  digitalWrite(leftMotorForward, HIGH);
  digitalWrite(leftMotorBackward, LOW);
  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, HIGH);

  analogWrite(leftMotorSpeed, 180);
  analogWrite(rightMotorSpeed, 180);

  delay(durationMs);
  stopRobot();
}

// Function to turn robot left
void turnLeft(int durationMs) {
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, HIGH);
  digitalWrite(rightMotorForward, HIGH);
  digitalWrite(rightMotorBackward, LOW);

  analogWrite(leftMotorSpeed, 180);
  analogWrite(rightMotorSpeed, 180);

  delay(durationMs);
  stopRobot();
}

// Function to stop the robot
void stopRobot() {
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, LOW);
  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, LOW);
}", "filename": "obstacle_avoiding_robot.ino"}, "tool_call_id": "sarm8nhnr"}, {"agent": "coding_agent", "event": "result", "tool": "save_code", "content": "{"saved": true, "path": "/Users/rayentabet/Desktop/InMind/Assignment_10/generated/code/obstacle_avoiding_robot.ino"}", "tool_call_id": "sarm8nhnr"}, {"agent": "coding_agent", "event": "call", "tool": "validate_code", "arguments": {"filename": "obstacle_avoiding_robot.ino"}, "tool_call_id": "s8d756fvv"}, {"agent": "coding_agent", "event": "result", "tool": "validate_code", "content": "{"valid": true, "errors": []}", "tool_call_id": "s8d756fvv"}, {"agent": "robot_visualization_agent", "event": "call", "tool": "save_openscad", "arguments": {"model_name": "obstacle_avoiding_robot", "code": "// Robot dimensions
chassis_w = 100;
chassis_l = 120;
chassis_h = 10;

wheel_r = 30;
wheel_w = 10;

sensor_size = 20;

// Chassis
color("gray") cube([chassis_w, chassis_l, chassis_h], center=true);

// Wheels
color("black") {
    translate([-chassis_w/2 - wheel_w/2, -chassis_l/4, 0]) rotate([0, 90, 0]) cylinder(r=wheel_r, h=wheel_w);
    translate([chassis_w/2 - wheel_w/2, -chassis_l/4, 0]) rotate([0, 90, 0]) cylinder(r=wheel_r, h=wheel_w);
}

// Controller (Arduino)
color("blue") translate([0, 0, chassis_h/2 + 5]) cube([50, 70, 10], center=true);

// Battery
color("green") translate([0, 30, chassis_h/2 + 5]) cube([40, 30, 15], center=true);

// Sensor
color("silver") translate([0, chassis_l/2 + sensor_size/2, chassis_h/2]) cube([sensor_size*2, sensor_size/2, sensor_size], center=true);
